INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(25301, 'John 8:47', 'John', 8, 47, '&nbsp;څوک چې د خُدائ پاک دى هغوئ د خُدائ پاک کلام قبلوى. په کومه وجه چې تاسو ورته توجو نۀ ورکوئ هغه دا چې تاسو د خُدائ پاک نه نۀ يئ.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25302, 'John 8:48', 'John', 8, 48, '&nbsp;يهوديانو جواب ورکړو چې، ”ولې زمونږ دا وينا رښتيا نۀ ده چې تۀ سامرى يې او په تا پيريان ناست دى؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25303, 'John 8:49', 'John', 8, 49, '&nbsp;عيسىٰ وفرمائيل چې، ”په ما پيريان نۀ دى ناست. خو زۀ د خپل پلار عزت کوم خو په دې تاسو ما بې‌عزته کوئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25304, 'John 8:50', 'John', 8, 50, '&nbsp;زۀ خپله لوئى نۀ غواړم بلکې يو ذات شته چې هغه يې غواړى او هغه صحيح فېصله کوونکے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25305, 'John 8:51', 'John', 8, 51, '&nbsp;زۀ تاسو ته رښتيا وايم، کۀ څوک زما په کلام عمل کوى نو هغه به هيڅکله نۀ مرى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25306, 'John 8:52', 'John', 8, 52, '&nbsp;يهوديانو هغۀ ته ووئيل چې، ”اوس زمونږ پوره يقين دے چې په تا پيرے ناست دے. اِبراهيم خو وفات دے او نبيان هم وفات شوى دى او بيا هم تۀ وائې چې، کۀ څوک زما په کلام عمل وکړى نو هغه به هيڅکله نۀ مرى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25307, 'John 8:53', 'John', 8, 53, '&nbsp;ولې تۀ زمونږ د پلار اِبراهيم نه لوئ يې څۀ، څوک چې وفات دے؟ او نبيان هم وفات شوى دى. نو تۀ خپل ځان څۀ ګڼې؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25308, 'John 8:54', 'John', 8, 54, '&nbsp;عيسىٰ جواب ورکړو، ”کۀ چرې زۀ د خپل ځان لوئى وکړم نو زما لوئى بې‌مطلبه ده. هغه څوک چې ما له لوئى راکوى هغه زما پلار دے د چا په حقله چې تاسو وايئ چې هغه زمونږ خُدائ پاک دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25309, 'John 8:55', 'John', 8, 55, '&nbsp;اګر کۀ تاسو هغه نۀ پېژنئ. خو زۀ يې پېژنم. کۀ چرې ما دا ووئيل چې زۀ هغه نۀ پېژنم نو زۀ به هم ستاسو په شان دروغژن يم. خو زۀ هغه پېژنم او د هغۀ په کلام عمل کوم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25310, 'John 8:56', 'John', 8, 56, '&nbsp;ستاسو پلار اِبراهيم په دې خوشحاله وو چې هغه به زما ورځ ووينى. او هغۀ دا ورځ وليدله او خوشحاله شو.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25311, 'John 8:57', 'John', 8, 57, '&nbsp;يهوديانو جواب ورکړو چې، ”تۀ خو لا د پنځوسو کالو هم نۀ يې، نو اِبراهيم دې څنګه وليدو؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25312, 'John 8:58', 'John', 8, 58, '&nbsp;عيسىٰ وفرمائيل، ”زۀ تاسو ته رښتيا وايم، چې اِبراهيم لا پېدا شوے نۀ وو چې زۀ موجود وم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25313, 'John 8:59', 'John', 8, 59, '&nbsp;نو په دې هغوئ د عيسىٰ د ويشتو پسې کاڼى راواخستل خو عيسىٰ خپل ځان په ډډه کړو او د خُدائ د کور نه ووتو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25314, 'John 9:1', 'John', 9, 1, '&nbsp;عيسىٰ چې په لاره تېرېدو نو يو سړے يې وليدو چې پېدائشى ړوند وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25315, 'John 9:2', 'John', 9, 2, '&nbsp;د هغۀ مريدانو ترې تپوس وکړو چې، ”اُستاذه، ګناه چا کړې ده، دې سړى او کۀ د دۀ مور او پلار، چې دے ړوند پېدا شوے دے؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25316, 'John 9:3', 'John', 9, 3, '&nbsp;عيسىٰ جواب ورکړو، ”نۀ دې سړى او نۀ د دۀ مور پلار ګناه کړې ده. بلکې هغه ځکه ړوند پېدا شو چې د خُدائ پاک قُدرت په دۀ کښې څرګند شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25317, 'John 9:4', 'John', 9, 4, '&nbsp;ترڅو چې لا ورځ ده مونږ له د هغۀ کار کول په کار دى چا چې زۀ رالېږلے يم، شپه راروانه ده چې هيڅوک په کښې کار نۀ شى کولے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25318, 'John 9:5', 'John', 9, 5, '&nbsp;نو ترڅو چې زۀ په دُنيا کښې يم، زۀ د دُنيا نُور يم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25319, 'John 9:6', 'John', 9, 6, '&nbsp;دې وئيلو سره عيسىٰ په زمکه وتُوکل او په توکاڼو يې خټه جوړه کړله او هغه يې د هغه سړى په سترګو ومږله،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25320, 'John 9:7', 'John', 9, 7, '&nbsp;او ورته يې وفرمائيل چې، ”لاړ شه او د سيلوم په تالاب کښې يې ووينځه.“ د دې لفظ معنىٰ ده، لېږلے شوے، نو هغه سړے لاړو، سترګې يې ووينځلې او چې واپس راغلو بينا شوے وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25321, 'John 9:8', 'John', 9, 8, '&nbsp;بيا د هغۀ ګاونډيانو او هغه چا چې دے يې پېژندو چې خير به يې غوښتو، هغوئ ووئيل چې، ”ولې دا هغه سړے نۀ دے چې ناست به وو او خير به يې غوښتو؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25322, 'John 9:9', 'John', 9, 9, '&nbsp;ځينو ووئيل، ”آو، هم دا هغه سړے دے،“ او نورو ووئيل، ”نه، دا د هغۀ په شان دے.“ هغۀ په خپله ووئيل چې، ”زۀ هم هغه سړے يم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25323, 'John 9:10', 'John', 9, 10, '&nbsp;هغوئ ترې تپوس وکړو، ”نو ستا سترګې څنګه بينا شوې؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25324, 'John 9:11', 'John', 9, 11, '&nbsp;هغۀ جواب ورکړو، ”يو سړے چې نوم يې عيسىٰ دے هغۀ خټه جوړه کړه، او زما په سترګو يې ومږله او راته يې وفرمائيل چې د سيلوم تالاب ته لاړ شه او وې وينځه. بيا زۀ لاړم او ومې وينځلې او بينا شوم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25325, 'John 9:12', 'John', 9, 12, '&nbsp;هغوئ تپوس وکړو چې، ”هغه دے چرته؟“ هغۀ جواب ورکړو، ”ما ته پته نشته.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25326, 'John 9:13', 'John', 9, 13, '&nbsp;هغه سړے چې مخکښې ړوند وو هغوئ فريسيانو له راوستو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25327, 'John 9:14', 'John', 9, 14, '&nbsp;دا د سبت ورځ وه چې عيسىٰ خټه جوړه کړه او د هغۀ سترګې يې بينا کړې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25328, 'John 9:15', 'John', 9, 15, '&nbsp;بيا فريسيانو ترې هم تپوسونه شروع کړل چې، ”تۀ څنګه بينا شوې؟“ سړى هغوئ ته ووئيل، ”هغۀ زما په سترګو خټه ومږله، بيا هغه ما ووينځلې او اوس زۀ ليدے شم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25329, 'John 9:16', 'John', 9, 16, '&nbsp;ځينو فريسيانو ووئيل چې، ”دا سړے د خُدائ پاک د طرفه نۀ دے ځکه چې د سبت د ورځې احترام نۀ کوى.“ خو نورو ووئيل چې، ”يو ګناه ګار سړے څنګه داسې معجزه کولے شى؟“ او په هغوئ کښې اختلاف پېدا شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25330, 'John 9:17', 'John', 9, 17, '&nbsp;نو هغوئ د هغه ړوند سړى نه بيا تپوس وکړو چې، ”ستا د هغۀ په حقله څۀ خيال دے؟ ځکه چې هغۀ ستا سترګې بينا کړې دى.“ هغۀ جواب ورکړو چې، ”هغه يو نبى دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25331, 'John 9:18', 'John', 9, 18, '&nbsp;خو يهوديانو په دې باور نۀ کولو چې دا سړے ړوند وو او بينا شو ترڅو چې هغوئ د هغۀ مور او پلار راوغوښتل', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25332, 'John 9:19', 'John', 9, 19, '&nbsp;او تپوس يې ترې وکړو چې، ”دا ستاسو زوئ دے، څوک چې تاسو وايئ چې ړوند پېدا شوے وو؟ نو اوس دے څنګه ليدلے شى؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25333, 'John 9:20', 'John', 9, 20, '&nbsp;مور او پلار يې جواب ورکړو، ”مونږ ته دا پته ده چې دا زمونږ زوئ دے او چې دے پېدائشى ړوند دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25334, 'John 9:21', 'John', 9, 21, '&nbsp;خو مونږ ته پته نشته چې دا څنګه دے اوس ليدلے شى، او نۀ مونږ ته پته شته چې چا د دۀ سترګې بينا کړې. د دۀ نه تپوس وکړئ، دے زلمے دے، دے به په خپله حال ووائى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25335, 'John 9:22', 'John', 9, 22, '&nbsp;د هغۀ مور او پلار د يرې نه داسې ووئيل ځکه چې هغوئ د يهوديانو نه ويرېدل. نو يهوديانو د مخکښې نه دا فېصله کړې وه چې څوک هم عيسىٰ ومنى چې مسيح دے نو هغه به د عبادتخانې نه وشړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25336, 'John 9:23', 'John', 9, 23, '&nbsp;هم دغه وجه وه چې مور پلار يې ووئيل چې هغه زلمے دے، تپوس ترې وکړئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25337, 'John 9:24', 'John', 9, 24, '&nbsp;نو بيا په دوېم ځل هغوئ هغه سړے راوغوښتو څوک چې ړوند وو او ورته يې ووئيل، ”خُدائ پاک ته مخ کړه او رښتيا ووايه، خو مونږ ته دا پته ده چې دا سړے ګناه ګار دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25338, 'John 9:25', 'John', 9, 25, '&nbsp;هغۀ جواب ورکړو، ”ما ته پته نشته چې دے ګناه ګار دے او کۀ نه، خو زۀ د يو څيز نه خبر يم، هغه دا چې زۀ ړوند وم او اوس بينا شوے يم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25339, 'John 9:26', 'John', 9, 26, '&nbsp;هغوئ ترې تپوس وکړو چې، ”هغۀ تا سره څۀ وکړل؟ هغۀ ستا سترګې څنګه بينا کړې؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25340, 'John 9:27', 'John', 9, 27, '&nbsp;هغۀ جواب ورکړو چې، ”ما خو تاسو ته ووئيل خو تاسو غوږ نۀ کېښودو، نو تاسو دا بيا ولې اورېدل غواړئ؟ ولې تاسو هم د هغۀ مريدان جوړېدل غواړئ څۀ؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25341, 'John 9:28', 'John', 9, 28, '&nbsp;نو بيا هغوئ په کنځلو شول او ورته يې ووئيل، ”تۀ د هغۀ مريد يې، خو مونږ د موسىٰ يُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25342, 'John 9:29', 'John', 9, 29, '&nbsp;مونږ ته پته ده چې خُدائ پاک د موسىٰ سره خبرې کړې وې خو د دې سړى نه خبر نۀ يُو چې دے د کومه راغلے دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25343, 'John 9:30', 'John', 9, 30, '&nbsp;سړى جواب ورکړو چې، ”څومره د حېرانتيا خبره ده چې تاسو ته دا پته نشته چې هغه د کومه راغلے دے، خو بيا هم هغۀ زما سترګې بينا کړې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25344, 'John 9:31', 'John', 9, 31, '&nbsp;مونږ ته پته ده چې خُدائ پاک د ګناهګارو نۀ اورى، خو هغه د هغه چا اورى چې د هغۀ عبادت کوى او د هغۀ رضا پوره کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25345, 'John 9:32', 'John', 9, 32, '&nbsp;د دُنيا د پېدايښت نه لا چا دا نۀ دى اورېدلى چې چا د پېدائشى ړوند سترګې بينا کړې دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25346, 'John 9:33', 'John', 9, 33, '&nbsp;کۀ دا سړے د خُدائ پاک د طرفه نۀ وے نو هغۀ هيڅ نۀ شو کولے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25347, 'John 9:34', 'John', 9, 34, '&nbsp;هغوئ ورته ووئيل چې، ”تۀ خو په خپله بلکل ګناه ګار پېدا شوے يې او اوس مونږ ته د تعليم راکولو کوشش کوې؟“ نو بيا هغوئ هغه د عبادتخانې نه وشړلو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25348, 'John 9:35', 'John', 9, 35, '&nbsp;کله چې عيسىٰ په دې خبر شو چې هغوئ هغه شړلے دے، نو عيسىٰ هغه پېدا کړو او تپوس يې ترې وکړو، ”ستا په اِبن آدم ايمان شته؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25349, 'John 9:36', 'John', 9, 36, '&nbsp;سړى جواب ورکړو، ”مالِکه، ما ته ووايه هغه څوک دے نو چې زۀ په هغۀ ايمان راوړم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25350, 'John 9:37', 'John', 9, 37, '&nbsp;عيسىٰ هغۀ ته وفرمائيل چې، ”تا هغه وليدو، څوک چې تا سره خبرې کوى هم هغه دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25351, 'John 9:38', 'John', 9, 38, '&nbsp;هغۀ ووئيل، ”مالِکه، زما پرې ايمان دے.“ او هغه ورته په سجده پرېوتو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25352, 'John 9:39', 'John', 9, 39, '&nbsp;عيسىٰ وفرمائيل چې، ”زۀ دې دُنيا ته د عدالت دپاره راغلے يم چې ړاندۀ بينا شى او څوک چې ځان بينا ګڼى هغه ړاندۀ شى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25353, 'John 9:40', 'John', 9, 40, '&nbsp;ځينى فريسيان چې د هغۀ سره نزدې ولاړ وُو د هغۀ دا خبرې يې واورېدلې او تپوس يې ترې وکړو، ”ولې مونږ ړاندۀ يُو څۀ؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25354, 'John 9:41', 'John', 9, 41, '&nbsp;عيسىٰ هغوئ ته وفرمائيل، ”کۀ چرې تاسو ړاندۀ وے نو ستاسو ګناه به نۀ وه خو اوس چې تاسو دا وايئ چې مونږ بينا يُو، نو په دې تاسو ګناه ګار پاتې شوئ.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25355, 'John 10:1', 'John', 10, 1, '&nbsp;”زۀ تاسو ته رښتيا وايم چې هر څوک چې د ګډو شپول ته په دروازې نۀ ورننوځى خو په بله لاره وراوړى هغه غل او ډاکو دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25356, 'John 10:2', 'John', 10, 2, '&nbsp;خو کوم سړے چې په دروازه ورننوځى هغه د ګډو شپونکے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25357, 'John 10:3', 'John', 10, 3, '&nbsp;څوکيدار هغۀ ته دروازه کولاووى، او ګډې د هغۀ آواز اورى او هغه خپلې ګډې په نوم رابلى او هغوئ په هغۀ پسې روانې وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25358, 'John 10:4', 'John', 10, 4, '&nbsp;کله چې هغه خپلې ټولې ګډې رابهر کړې نو هغه ترې وړاندې ځى او ګډې ورپسې، ځکه چې هغوئ د هغۀ آواز پېژنى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25359, 'John 10:5', 'John', 10, 5, '&nbsp;هغوئ به نا آشنا سړى پسې چرې هم نۀ ځى. بلکې هغوئ به د هغۀ نه وتښتى ځکه چې هغوئ د نا آشنا سړى آواز نۀ پېژنى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25360, 'John 10:6', 'John', 10, 6, '&nbsp;عيسىٰ هغوئ ته دا مِثال ووئيلو خو هغوئ په دې پوهه نۀ شول چې د هغۀ د دې نه مطلب څۀ وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25361, 'John 10:7', 'John', 10, 7, '&nbsp;نو عيسىٰ هغوئ ته بيا وفرمائيل چې، ”زۀ تاسو ته رښتيا وايم چې زۀ د ګډو دپاره دروازه يم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25362, 'John 10:8', 'John', 10, 8, '&nbsp;هغوئ ټول چې زما نه مخکښې راغلى وُو غلۀ او ډاکوان وُو، خو ګډو هغوئ ته غوږ ونۀ نيولو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25363, 'John 10:9', 'John', 10, 9, '&nbsp;زۀ دروازه يم. څوک چې زما په وسيله ننوځى هغه به بچ شى. هغه به دننه بهر تلے راتلے شى او د څرن ځائ به ومومى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25364, 'John 10:10', 'John', 10, 10, '&nbsp;غل صرف د غلا د قتل او د تباهۍ دپاره راځى خو زۀ دې له راغلے يم چې خلق ژوندون حاصل کړى او په مکمل ډول پُرسکونه وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25365, 'John 10:11', 'John', 10, 11, '&nbsp;زۀ ښۀ شپونکے يم او ښۀ شپونکے د ګډو دپاره خپل سر ورکوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25366, 'John 10:12', 'John', 10, 12, '&nbsp;خو مزدور چې نۀ شپون وى او نۀ يې ګډې خپلې وى، کله چې هغه ليوۀ په راتلو ووينى نو ګډې په ځائ پرېږدى او وتښتى. ليوۀ رمه راګېره کړى او ګډې خورې ورې کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25367, 'John 10:13', 'John', 10, 13, '&nbsp;هغه ځکه تښتى چې مزدور دے او د ګډو هيڅ پرواه نۀ کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25368, 'John 10:14', 'John', 10, 14, '&nbsp;زۀ ښۀ شپون يم. زۀ خپلې ګډې پېژنم او زما ګډې ما پېژنى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25369, 'John 10:15', 'John', 10, 15, '&nbsp;څنګه چې ما پلار پېژنى او زۀ پلار پېژنم، او زۀ خپل ځان د ګډو دپاره قربانوم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25370, 'John 10:16', 'John', 10, 16, '&nbsp;زما نورې ګډې هم شته چې په دې شپول کښې نشته، زۀ به هغوئ هم ضرور دلته راولم. هغوئ به زما آواز اورى، او بيا به يوه رمه وى او شپونکے به يې هم يو وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25371, 'John 10:17', 'John', 10, 17, '&nbsp;په دې وجه پلار ما سره مينه کوى ځکه چې زۀ خپل ځان قربانوم د دې دپاره چې دا بيا ومومم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25372, 'John 10:18', 'John', 10, 18, '&nbsp;دا زما نه څوک نۀ اخلى، خو زۀ دا په خپله مرضۍ قربانوم. دا زما اختيار دے چې ځان قربان کړم او دا مې هم اختيار دے چې دا زۀ بيا ومومم. دا حُکم ما ته خپل پلار راکړے دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25373, 'John 10:19', 'John', 10, 19, '&nbsp;د دې خبرو په وجه بيا په يهوديانو کښې بې‌اتفاقى راغله.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25374, 'John 10:20', 'John', 10, 20, '&nbsp;په هغوئ کښې ډېرو وئيل چې، ”په دۀ پيريان ناست دى او دے پاګل دے، ولې تاسو دۀ ته غوږ ږدئ؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25375, 'John 10:21', 'John', 10, 21, '&nbsp;خو نورو وئيل چې، ”په چا چې پيريان ناست وى هغه داسې خبرې نۀ شى کولے. ولې پيرے د ړوند سترګې روغولے شى څۀ؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25376, 'John 10:22', 'John', 10, 22, '&nbsp;دا د ژمى ورځې وې او په يروشلم کښې د خُدائ د کور د وقف کېدو اختر وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25377, 'John 10:23', 'John', 10, 23, '&nbsp;او عيسىٰ د خُدائ په کور کښې د سليمان په برانډه کښې ګرځېدو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25378, 'John 10:24', 'John', 10, 24, '&nbsp;يهوديان د هغۀ نه راچاپېره شول او ورته يې ووئيل، ”ترڅو پورې به تۀ مونږ په شک کښې ساتې؟ کۀ تۀ مسيح يې نو مونږ ته صفا صفا ووايه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25379, 'John 10:25', 'John', 10, 25, '&nbsp;عيسىٰ جواب ورکړو چې، ”ما تاسو ته ووئيل خو تاسو پرې يقين نۀ کوئ. زۀ چې کوم کارونه د خپل پلار په نوم کوم، هغه زما ګواه دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25380, 'John 10:26', 'John', 10, 26, '&nbsp;خو تاسو پرې يقين نۀ کوئ ځکه چې تاسو زما ګډې نۀ يئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25381, 'John 10:27', 'John', 10, 27, '&nbsp;زما ګډې زما آواز اورى، زۀ هغوئ پېژنم او هغوئ ما پسې راځى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25382, 'John 10:28', 'John', 10, 28, '&nbsp;زۀ هغوئ له د تل ژوندون ورکوم او هغوئ به هيڅکله هم هلاک نۀ شى او هيڅوک به يې هم زما د لاس نه ونۀ شوکوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25383, 'John 10:29', 'John', 10, 29, '&nbsp;زما پلار چې ما ته هغوئ حواله کړى دى هغه د هر څۀ نه زورَور دے او هيڅ څوک دا د پلار د لاس نه نۀ شى شوکولے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25384, 'John 10:30', 'John', 10, 30, '&nbsp;زۀ او زما پلار يو يُو.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25385, 'John 10:31', 'John', 10, 31, '&nbsp;بيا يهوديانو عيسىٰ پسې کاڼى راوخستل چې پرې وې ولى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25386, 'John 10:32', 'John', 10, 32, '&nbsp;خو عيسىٰ هغوئ ته وفرمائيل چې، ”ما تاسو ته د پلار له طرفه ډېر نېک کارونه وښودل. نو تاسو ما د کوم کار په وجه سنګساروئ؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25387, 'John 10:33', 'John', 10, 33, '&nbsp;يهوديانو ورله جواب ورکړو چې، ”مونږ تا د څۀ نېک کار په وجه نۀ سنګساروو خو د کُفر په سبب، ځکه چې تۀ خو صرف انسان يې او د خُدايئ دعوىٰ کوې.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25388, 'John 10:34', 'John', 10, 34, '&nbsp;عيسىٰ جواب ورکړو چې، ”ولې ستاسو په شريعت کښې دا نۀ دى ليکلے شوى چې، ”ما وفرمائيل چې تاسو خُدايان يئ؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25389, 'John 10:35', 'John', 10, 35, '&nbsp;هغه خلق خُدايان بللے کېدل چا ته چې د خُدائ پاک کلام راغلے وو، خو مونږ په دې پوهيږو چې صحيفې بدلېدے نۀ شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25390, 'John 10:36', 'John', 10, 36, '&nbsp;ولې تاسو دا وئيلے شئ چې څوک چې پلار مقدس کړے دے او دُنيا ته يې رالېږلے دے، هغه کُفر کوى ځکه چې ما وفرمائيل چې زۀ د خُدائ پاک زوئ يم؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25391, 'John 10:37', 'John', 10, 37, '&nbsp;کۀ چرې زۀ د خپل پلار کارونه نۀ کوم، نو په ما ايمان مۀ راوړئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25392, 'John 10:38', 'John', 10, 38, '&nbsp;خو کۀ زۀ يې کوم، کۀ څۀ هم تاسو په ما ايمان نۀ راوړئ، نو زما په کارونو ايمان راوړئ د دې دپاره چې تاسو ته پته ولګى او پوهه شئ چې پلار په ما کښې دے او زۀ په پلار کښې يم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25393, 'John 10:39', 'John', 10, 39, '&nbsp;نو هغوئ يو ځلې بيا د هغۀ د نيولو کوشش وکړو خو هغه د هغوئ د لاس نه ووتو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25394, 'John 10:40', 'John', 10, 40, '&nbsp;عيسىٰ بيا د اُردن د سيند پورې غاړه هغه ځائ ته لاړو چرته چې به يحيىٰ اول بپتسمه ورکوله. او هغه هلته پاتې شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25395, 'John 10:41', 'John', 10, 41, '&nbsp;ګڼ خلق ورله راغلل او هغوئ وئيل چې، ”يحيىٰ مونږ ته يوه معجزه هم نۀ وه ښکاره کړې، خو هغۀ چې څۀ د دې سړى په حقله وئيلى وُو هغه رښتيا دى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25396, 'John 10:42', 'John', 10, 42, '&nbsp;او په هغه ځائ کښې ډېرو خلقو په عيسىٰ ايمان راوړلو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25397, 'John 11:1', 'John', 11, 1, '&nbsp;نو اوس لعزر نومې سړے ناجوړه وو، چې د بيتِ‌عنياه وو کوم چې د مريمې او د هغې د خور مرتا کلے وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25398, 'John 11:2', 'John', 11, 2, '&nbsp;دا د هغه مريم ورور لعزر ناجوړه وو چا چې په مالِک عطر اچولى وُو او د هغۀ پښې يې په خپلو وېښتو وچې کړې وې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25399, 'John 11:3', 'John', 11, 3, '&nbsp;نو خوېندو يې عيسىٰ له خبر ورولېږلو چې، ”مالِکه، چا سره چې تۀ مينه کوې هغه بيمار دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25400, 'John 11:4', 'John', 11, 4, '&nbsp;خو کله چې عيسىٰ دا واورېدل نو وې وفرمائيل، ”دا بيمارى د مرګ نۀ ده، دا خو د خُدائ پاک د جلال څرګندولو دپاره ده نو چې د خُدائ پاک زوئ د دې په وسيله جلال ومومى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');